package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Move grouping, retain operand order, and check both the new inner value and total. */
public final class AssociativeArithmetic {
 private AssociativeArithmetic(){}
 public static final String ADD="associativeAddition",MUL="associativeMultiplication";
 public static final List<Catalog.Skill> SKILLS=List.of(new Catalog.Skill(ADD,"덧셈의 결합법칙",6,1,1,"",ADD,1000000,"add20","세 수의 순서는 그대로 두고 괄호의 묶음을 바꾸어도 합은 같다."),new Catalog.Skill(MUL,"곱셈의 결합법칙",6,1,1,"",MUL,1000000,"tables","세 수의 순서는 그대로 두고 괄호의 묶음을 바꾸어도 곱은 같다."));
 private static final String INSTRUCTION="수의 순서는 그대로 두고 묶음을 바꾸세요.\n빈칸, 바꾼 괄호 안 값, 전체 계산값을 쓰세요.";
 private static final Pattern LEFT=Pattern.compile("^\\(([0-9]{1,7}) ([+×]) ([0-9]{1,7})\\) ([+×]) ([0-9]{1,7}) = □ ([+×]) \\(□ ([+×]) □\\)$"),RIGHT=Pattern.compile("^([0-9]{1,7}) ([+×]) \\(([0-9]{1,7}) ([+×]) ([0-9]{1,7})\\) = \\(□ ([+×]) □\\) ([+×]) □$");
 public record Givens(int a,int b,int c,int direction,long originalInner,long newInner,long total){}
 public static boolean supports(String id){return ADD.equals(id)||MUL.equals(id);}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null||!q.prompt.endsWith("\n"+INSTRUCTION))return null;String math=q.prompt.substring(0,q.prompt.length()-INSTRUCTION.length()-1),op=ADD.equals(q.skillId)?"+":"×";Matcher m=LEFT.matcher(math);int direction=0;if(!m.matches()){m=RIGHT.matcher(math);direction=1;if(!m.matches())return null;}for(int i:List.of(2,4,6,7))if(!op.equals(m.group(i)))return null;int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(3)),c=Integer.parseInt(m.group(5));if(a>1000000||b>1000000||c>1000000)return null;long ab=ADD.equals(q.skillId)?(long)a+b:(long)a*b,bc=ADD.equals(q.skillId)?(long)b+c:(long)b*c,total=ADD.equals(q.skillId)?ab+c:ab*c;if(ab>1000000||bc>1000000||total>1000000)return null;return new Givens(a,b,c,direction,direction==0?ab:bc,direction==0?bc:ab,total);}
 static Question make(String id,int a,int b,int c,int direction){if(direction<0||direction>1)throw new IllegalArgumentException("group direction");String op=ADD.equals(id)?"+":"×";String math=direction==0?"("+a+" "+op+" "+b+") "+op+" "+c+" = □ "+op+" (□ "+op+" □)":a+" "+op+" ("+b+" "+op+" "+c+") = (□ "+op+" □) "+op+" □";Question q=new Question(id,math+"\n"+INSTRUCTION,"");Givens g=read(q);if(g==null)throw new IllegalArgumentException("associative arithmetic domain");q.answers=new String[]{""+a,""+b,""+c,""+g.newInner,""+g.total};q.labels=new String[]{"첫째 빈칸","둘째 빈칸","셋째 빈칸","바꾼 괄호 안 값","전체 계산값"};q.stepSupport=false;attach(q);return q;}
 private record Segment(int first,int quotient,long start,long end,long width){}
 private record Products(int maximum,List<Segment> segments,long positive,long firstZero,long thirdZero,long middleZero){}
 private static Products cached;
 private static synchronized Products products(int max){if(cached!=null&&cached.maximum==max)return cached;List<Segment> segments=new ArrayList<>();long count=0;for(int b=1;b<=max;){int quotient=max/b,last=max/quotient;long width=BoundedProductIndices.count(quotient,false),end=count+(long)(last-b+1)*width;segments.add(new Segment(b,quotient,count,end,width));count=end;b=last+1;}cached=new Products(max,List.copyOf(segments),count,BoundedProductIndices.count(max,true),BoundedProductIndices.count(max,false),(max+1L)*(max+1L));return cached;}
 private static int[] positiveAt(Products d,long index){int low=0,high=d.segments.size()-1;while(low<high){int mid=(low+high)/2;if(index<d.segments.get(mid).end)high=mid;else low=mid+1;}Segment s=d.segments.get(low);long offset=index-s.start;int b=s.first+(int)(offset/s.width);int[] ac=BoundedProductIndices.at(s.quotient,offset%s.width,false);return new int[]{ac[0],b,ac[1]};}
 private static int[] zeroAt(Products d,int kind,long index){if(kind==0)return new int[]{(int)(index/(d.maximum+1L)),0,(int)(index%(d.maximum+1L))};int[] pair=BoundedProductIndices.at(d.maximum,index,kind==1);return kind==1?new int[]{0,pair[0],pair[1]}:new int[]{pair[0],pair[1],0};}
 private static Question productAt(Products d,long index){int direction=(int)(index%2);index/=2;int[] v;if(index<d.positive)v=positiveAt(d,index);else{index-=d.positive;if(index<d.middleZero)v=zeroAt(d,0,index);else{index-=d.middleZero;if(index<d.firstZero)v=zeroAt(d,1,index);else v=zeroAt(d,2,index-d.firstZero);}}return make(MUL,v[0],v[1],v[2],direction);}
 static Question next(String id,Random r,CurriculumLimits limits,Map<String,Integer> recent){int max=limits.givenMaximum(1000000);if(ADD.equals(id))return IndexedQuestionSupply.chooseLarge(2*ThreeNumberEstimation.combinations(max),i->{int[] v=ThreeNumberEstimation.at(max,i/2);return make(ADD,v[0],v[1],v[2],(int)(i%2));},r,limits,recent);Products d=products(max);boolean zero=d.positive==0||r.nextInt(8)==0;long count;java.util.function.LongFunction<Question> factory;if(zero){int kind=max==0?0:r.nextInt(3);count=2*(kind==0?d.middleZero:kind==1?d.firstZero:d.thirdZero);factory=i->{int[] v=zeroAt(d,kind,i/2);return make(MUL,v[0],v[1],v[2],(int)(i%2));};}else{count=2*d.positive;factory=i->{int[] v=positiveAt(d,i/2);return make(MUL,v[0],v[1],v[2],(int)(i%2));};}Question q=IndexedQuestionSupply.chooseLarge(count,factory,r,limits,recent);return recent.containsKey(q.signature())?IndexedQuestionSupply.chooseLarge(2*(d.positive+d.middleZero+d.firstZero+d.thirdZero),i->productAt(d,i),r,limits,recent):q;}
 static Checker.Result check(Question q,List<String> answers){Givens g=read(q);if(g==null||answers==null||answers.size()!=5)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"세 빈칸과 두 계산값 입력 필요");long[] values={g.a,g.b,g.c,g.newInner,g.total};for(int i=0;i<5;i++){String raw=answers.get(i);if(raw==null||!raw.trim().matches("[0-9]{1,7}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"세 빈칸과 두 계산값 입력 필요");if(Long.parseLong(raw.trim())!=values[i])return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 답 확인");}return new Checker.Result(Checker.Status.CORRECT,-1,"정답");}
 public static void attach(Question q){Givens g=read(q);if(g==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="associative-arithmetic-v1";for(int i=0;i<3;i++)h.step("수의 순서는 그대로 두세요. "+(i==0?"첫째":i==1?"둘째":"셋째")+" 빈칸을 쓰세요.",(i==0?"첫째":i==1?"둘째":"셋째")+" 빈칸 = ","",""+new int[]{g.a,g.b,g.c}[i]);h.step("원래 식의 괄호 안을 계산하세요.","원래 괄호 안 값 = ","",""+g.originalInner);h.step("원래 식의 전체 계산값을 쓰세요.","원래 전체 계산값 = ","",""+g.total);h.step("묶음을 바꾼 식의 괄호 안을 계산하세요.","바꾼 괄호 안 값 = ","",""+g.newInner);h.step("묶음을 바꾼 식의 전체 계산값을 쓰세요.","전체 계산값 = ","",""+g.total);q.studyGuide=h;}
}
